import pandas as pd

df = pd.read_excel('ers_food_availability_red_meat_poultry_fish.xlsx', sheet_name='Leading', header=None)

header_row = None
for idx, row in df.iterrows():
    if any('Beef' in str(s) for s in row):
        header_row = idx
        break

beef_col, chicken_col = None, None
for c in range(df.shape[1]):
    val = str(df.iloc[header_row, c])
    if 'Beef' in val:
        beef_col = c
    elif 'Chicken' in val:
        chicken_col = c

first_year = None
for r in range(header_row + 1, len(df)):
    try:
        yr = int(float(df.iloc[r, 0]))
        beef_val = float(df.iloc[r, beef_col])
        chick_val = float(df.iloc[r, chicken_col])
        if chick_val > beef_val:
            first_year = str(yr)
            break
    except (ValueError, TypeError):
        continue

result = first_year

