import pandas as pd

df = pd.read_excel('ers_food_availability_red_meat_poultry_fish.xlsx', sheet_name='Boneless', header=None)

meats = ['Beef', 'Veal', 'Pork', 'Lamb']
meat_cols = {}
for r in range(len(df)):
    row_str = [str(x).strip() for x in df.iloc[r]]
    if 'Beef' in row_str and 'Veal' in row_str:
        for c in range(df.shape[1]):
            val = str(df.iloc[r, c]).strip()
            if val in meats:
                meat_cols[val] = c
        break

for r in range(len(df)):
    try:
        if int(float(df.iloc[r, 0])) == 2019:
            vals = {m: float(df.iloc[r, col]) for m, col in meat_cols.items()}
            result = sorted(vals, key=vals.get, reverse=True)[:3]
            break
    except (ValueError, TypeError):
        continue

import pandas as pd

df = pd.read_excel('ers_food_availability_red_meat_poultry_fish.xlsx', sheet_name='Leading', header=None)

chicken_col = None
for r in range(len(df)):
    for c in range(df.shape[1]):
        if 'Chicken' in str(df.iloc[r, c]):
            chicken_col = c
            break
    if chicken_col is not None:
        break

count = 0
for r in range(len(df)):
    try:
        yr = int(float(df.iloc[r, 0]))
        if 2000 <= yr <= 2020:
            val = float(df.iloc[r, chicken_col])
            if val > 60:
                count += 1
    except (ValueError, TypeError):
        continue

result = count

import pandas as pd

df = pd.read_excel('ers_food_availability_red_meat_poultry_fish.xlsx', sheet_name='Carcass', header=None)

turkey_col = None
for r in range(len(df)):
    for c in range(df.shape[1]):
        if 'Turkey' in str(df.iloc[r, c]):
            turkey_col = c
            break
    if turkey_col is not None:
        break

vals = []
for r in range(len(df)):
    try:
        yr = int(float(df.iloc[r, 0]))
        if 2010 <= yr <= 2019:
            vals.append(float(df.iloc[r, turkey_col]))
    except (ValueError, TypeError):
        continue

result = round(sum(vals) / len(vals), 2)
